import json,sys,os
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def load(n): return json.loads((ROOT/'reports'/n).read_text())
c=load('documentation-contract-report.json'); t=load('documentation-test-report.json'); cli=load('documentation-cli-report.json')
report={'product':'t-understand','version':(ROOT/'VERSION').read_text().strip(),'phase':11,'phase_name':'Documentation Generation','status':'PASS' if all(x['status']=='PASS' for x in (c,t,cli)) else 'FAIL','inventory':{'canonical_documents':c['catalog_documents'],'schemas':8,'cli_commands':6,'canonical_format':'Markdown','traceability':'section-level'},'validation':{'contract_checks':c['checks'],'tests':t['tests'],'shared_cli_checks':cli['checks']},'assurances':{'model_bound':True,'memory_bound':True,'snapshot_bound':True,'immutable_docsets':True,'section_claim_evidence_binding':True,'business_inference_disclosure':True,'coverage_ledger':True,'document_invalidation':True,'deterministic_critique':True,'deterministic_verification':True},'explicit_limitations':['Generated documents describe the declared evidence scope, not undocumented requirements.','Human publication approval remains a separate lifecycle gate.','Third-party hosted rendering is not part of Phase 11.']}
(ROOT/'reports/phase-11-summary.json').write_text(json.dumps(report,indent=2)+'\n'); print(json.dumps(report,indent=2)); sys.stdout.flush(); os._exit(0 if report['status']=='PASS' else 1)
